# ============================================================
# PILLAR 1: ENCAPSULATION
# ============================================================
# WHAT: Bundling data + methods that operate on that data,
#        and restricting direct access to internals.
# WHY:  Protect data integrity, hide complexity.
# ANALOGY: A TV remote — you press buttons (public interface),
#          internal electronics are hidden (private).

class Employee:
    def __init__(self, name: str, salary: float):
        self.name = name            # public
        self._department = "Eng"    # protected (convention)
        self.__salary = salary      # private (name-mangled)

    @property
    def salary(self) -> float:
        return self.__salary

    @salary.setter
    def salary(self, value: float):
        if value < 0:
            raise ValueError("Salary cannot be negative")
        self.__salary = value

    def get_annual_salary(self) -> float:
        return self.__salary * 12

# ============================================================
# PILLAR 2: INHERITANCE
# ============================================================
# WHAT: A class (child) can inherit attributes/methods from
#        another class (parent).
# WHY:  Code reuse, establish relationships.
# ANALOGY: Children inherit traits from parents.

class Animal:
    def __init__(self, name: str):
        self.name = name

    def speak(self) -> str:
        raise NotImplementedError("Subclasses must implement speak()")

    def __str__(self) -> str:
        return f"{self.__class__.__name__}: {self.name}"

class Dog(Animal):
    def speak(self) -> str:
        return f"{self.name} says Woof!"

class Cat(Animal):
    def speak(self) -> str:
        return f"{self.name} says Meow!"

# --- Multiple Inheritance & MRO ---
class Flyable:
    def fly(self):
        return "Flying!"

class Swimmable:
    def swim(self):
        return "Swimming!"

class Duck(Animal, Flyable, Swimmable):
    def speak(self) -> str:
        return f"{self.name} says Quack!"

duck = Duck("Donald")
print(duck.speak())  # Donald says Quack!
print(duck.fly())    # Flying!
print(duck.swim())   # Swimming!

# MRO — Method Resolution Order
print(Duck.__mro__)
# (Duck, Animal, Flyable, Swimmable, object)
# Python uses C3 Linearization algorithm

# ============================================================
# PILLAR 3: POLYMORPHISM
# ============================================================
# WHAT: Same interface, different implementations.
# WHY:  Write generic code that works with different types.
# ANALOGY: A "start" button works differently on a car vs microwave.

def make_animal_speak(animal: Animal) -> str:
    """Works with ANY Animal subclass — polymorphism!"""
    return animal.speak()

animals = [Dog("Rex"), Cat("Whiskers"), Duck("Daffy")]
for a in animals:
    print(make_animal_speak(a))
# Rex says Woof!
# Whiskers says Meow!
# Daffy says Quack!

# --- Duck Typing (Python's approach to polymorphism) ---
# "If it walks like a duck and quacks like a duck, it IS a duck."
# Python doesn't check type — it checks if the method EXISTS.

class Robot:
    """Not an Animal subclass, but has speak() method."""
    def speak(self) -> str:
        return "Beep boop!"

# This works even though Robot doesn't inherit from Animal!
print(make_animal_speak(Robot()))  # Works due to duck typing

# --- Operator Overloading (Polymorphism via magic methods) ---
class Vector:
    def __init__(self, x: float, y: float):
        self.x, self.y = x, y

    def __add__(self, other):
        return Vector(self.x + other.x, self.y + other.y)

    def __mul__(self, scalar):
        return Vector(self.x * scalar, self.y * scalar)

    def __repr__(self):
        return f"Vector({self.x}, {self.y})"

v1 = Vector(1, 2)
v2 = Vector(3, 4)
print(v1 + v2)    # Vector(4, 6) — __add__
print(v1 * 3)     # Vector(3, 6) — __mul__

# ============================================================
# PILLAR 4: ABSTRACTION
# ============================================================
# WHAT: Hide complex implementation, expose simple interface.
# WHY:  Reduce complexity, enforce contracts.
# ANALOGY: You drive a car without knowing how the engine works.

from abc import ABC, abstractmethod

class PaymentProcessor(ABC):
    """Abstract base class — cannot be instantiated directly."""

    @abstractmethod
    def process_payment(self, amount: float) -> bool:
        """Subclasses MUST implement this."""
        pass

    @abstractmethod
    def refund(self, transaction_id: str) -> bool:
        pass

    def validate_amount(self, amount: float) -> bool:
        """Concrete method — shared by all subclasses."""
        return amount > 0

class StripePayment(PaymentProcessor):
    def process_payment(self, amount: float) -> bool:
        if not self.validate_amount(amount):
            return False
        print(f"Processing ${amount} via Stripe")
        return True

    def refund(self, transaction_id: str) -> bool:
        print(f"Refunding {transaction_id} via Stripe")
        return True

class PayPalPayment(PaymentProcessor):
    def process_payment(self, amount: float) -> bool:
        print(f"Processing ${amount} via PayPal")
        return True

    def refund(self, transaction_id: str) -> bool:
        print(f"Refunding {transaction_id} via PayPal")
        return True

# processor = PaymentProcessor()  # TypeError! Can't instantiate abstract class
processor = StripePayment()
processor.process_payment(99.99)
```

#### 📋 7 Conceptual Interview Questions

**Q1: What are the four pillars of OOP?**
> **Encapsulation**: bundling data + methods, restricting access. **Inheritance**: child class reuses parent class code. **Polymorphism**: same method name, different behavior based on object type. **Abstraction**: hide complexity, show only essential features.

**Q2: What is the difference between abstraction and encapsulation?**
> **Abstraction** hides *what* the implementation does (using abstract classes/interfaces). **Encapsulation** hides *how* it stores/manages data (using private attributes, properties). Abstraction is about design; encapsulation is about data protection.

**Q3: What is MRO (Method Resolution Order)?**
> The order in which Python searches classes in a multiple inheritance hierarchy to find a method. Uses **C3 Linearization** algorithm. Check with `ClassName.__mro__` or `ClassName.mro()`.

**Q4: What is the Diamond Problem? How does Python handle it?**
> When a class inherits from two classes that share a common ancestor, creating a diamond shape. Python solves it with MRO (C3 linearization) — each class appears only once in the resolution order.

**Q5: What is duck typing?**
> Python doesn't check an object's type — it checks if the object has the required method/attribute. "If it walks like a duck and quacks like a duck, it's a duck." This enables polymorphism without inheritance.

**Q6: When should you use inheritance vs composition?**
> **Inheritance**: "is-a" relationship (Dog IS an Animal). **Composition**: "has-a" relationship (Car HAS an Engine). Prefer composition — it's more flexible, avoids tight coupling, and follows "favor composition over inheritance" principle.

**Q7: What is an abstract class? Can it have concrete methods?**
> An abstract class (using `ABC`) cannot be instantiated and has at least one `@abstractmethod`. YES, it can also have concrete methods that provide shared functionality to all subclasses.

#### 📋 5 Scenario-Based Questions

**S1:** *Design a notification system that supports Email, SMS, and Push notifications.*
```python
from abc import ABC, abstractmethod

class Notifier(ABC):
    @abstractmethod
    def send(self, recipient: str, message: str) -> bool: ...

class EmailNotifier(Notifier):
    def send(self, recipient, message):
        print(f"Email to {recipient}: {message}")
        return True

class SMSNotifier(Notifier):
    def send(self, recipient, message):
        print(f"SMS to {recipient}: {message}")
        return True

# Usage — polymorphism
def notify_all(notifiers: list[Notifier], recipient: str, msg: str):
    for n in notifiers:
        n.send(recipient, msg)
```

**S2:** *A junior developer used inheritance where a `Stack` inherits from `list`. What's wrong?*
> A Stack should NOT inherit from list because it exposes all list methods (insert, sort, etc.) that break Stack's LIFO contract. Use **composition** instead: store a private list internally and expose only `push()`, `pop()`, `peek()`.

**S3:** *How would you implement a plugin system where third-party developers can add functionality?*
> Define an abstract base class as the plugin interface. Plugins subclass it and implement required methods. Use a registry (dict) to discover and load plugins dynamically.

**S4:** *You need a class hierarchy for shapes (Circle, Rectangle, Triangle) that calculates area and perimeter.*
```python
from abc import ABC, abstractmethod
import math

class Shape(ABC):
    @abstractmethod
    def area(self) -> float: ...
    @abstractmethod
    def perimeter(self) -> float: ...

class Circle(Shape):
    def __init__(self, radius: float):
        self.radius = radius
    def area(self): return math.pi * self.radius ** 2
    def perimeter(self): return 2 * math.pi * self.radius
```

**S5:** *How would you prevent a class from being subclassed?*
```python
class Final:
    def __init_subclass__(cls, **kwargs):
        raise TypeError(f"Cannot subclass {Final.__name__}")
```
